const idea = ($json.body && $json.body.ide) ? $json.body.ide : '';
const pref = ($json.body && $json.body.preferensi) ? $json.body.preferensi : {};
const designSystem = ($json.body && $json.body.design_system) ? String($json.body.design_system) : '';
const sertakanStack = (pref.sertakan_tech_stack === undefined) ? true : !!pref.sertakan_tech_stack;
const sertakanKode = (pref.sertakan_kode === undefined) ? true : !!pref.sertakan_kode;
const prompt = `Kamu adalah seorang Product Strategist senior yang berpengalaman membangun web dan aplikasi digital.

Pengguna mengirimkan sebuah ide mentah untuk aplikasi:

"${idea}"

PREFERENSI PENGGUNA (patuhi ini):
- Sertakan tech stack di PRD: ${sertakanStack ? 'YA' : 'TIDAK'}
- Sertakan kode/coding di PRD: ${sertakanKode ? 'YA' : 'TIDAK'}
- Design system yang dipilih: ${designSystem || 'belum ditentukan'}

Tugasmu - PIKIRKAN DENGAN SANGAT MATANG sebelum menetapkan arah:
1. Pahami dan identifikasi inti dari ide ini
2. Eksplorasi dan perkuat ide: siapa target penggunanya, apa problem utama yang diselesaikan, apa value proposition-nya
3. Tentukan scope awal: apakah ini web app, mobile app, atau keduanya
4. Identifikasi fitur-fitur inti yang WAJIB ada (must-have) vs nice-to-have
5. Tentukan tech complexity level: Simple / Medium / Complex
6. ANALISIS RISIKO & PELUANG: sebutkan risiko-risiko utama (teknis, bisnis, pasar, regulasi) beserta dampak dan mitigasinya, serta peluang-peluang yang bisa dimaksimalkan.
7. ANALISIS BIAYA: nilai dengan jujur apakah ada biaya yang perlu dikeluarkan untuk membangun aplikasi ini. Jika ada, sebutkan di komponen mana biaya keluar dan perkiraannya. Jika tidak ada biaya berarti, katakan demikian.

Output dalam format JSON berikut (tidak ada teks di luar JSON):
{
  "project_name": "nama singkat project",
  "ide_inti": "penjelasan 2-3 kalimat tentang ide",
  "target_pengguna": "deskripsi target user",
  "problem_yang_diselesaikan": "problem utama",
  "value_proposition": "nilai utama produk ini",
  "platform": "web / mobile / keduanya",
  "fitur_inti": ["fitur 1", "fitur 2", "dst"],
  "fitur_nice_to_have": ["fitur a", "fitur b"],
  "complexity_level": "Simple / Medium / Complex",
  "estimasi_skala": "MVP / Startup Product / Enterprise",
  "resiko": [
    { "resiko": "deskripsi risiko", "dampak": "Tinggi/Sedang/Rendah", "mitigasi": "cara memitigasi" }
  ],
  "peluang": ["peluang 1", "peluang 2"],
  "analisis_biaya": {
    "ada_biaya": true,
    "kesimpulan": "satu kalimat kesimpulan apakah ada biaya dan seberapa besar",
    "rincian_biaya": [
      { "komponen": "nama komponen biaya", "keterangan": "kenapa/untuk apa", "kira_kira": "perkiraan nominal atau rentang" }
    ]
  }
}`;
return { prompt };

