const ide = $('Prepare Generate Input').first().json.ide_result;
const designSystem = $('Prepare Generate Input').first().json.design_system || '';
const prompt = `Kamu adalah seorang Senior Software Architect dan Product Manager.

Berikut adalah hasil analisis ide sebuah aplikasi:

${JSON.stringify(ide)}

Design system UI yang dipilih pengguna: ${designSystem || 'belum ditentukan'}

Tugasmu: Pecah development aplikasi ini menjadi TAHAPAN-TAHAPAN eksekusi yang logis dan terstruktur.

ATURAN PENTING:
- Jumlah tahapan TIDAK BOLEH dipatok — sesuaikan dengan complexity_level dari hasil analisis
- Simple -> biasanya 3-4 tahapan
- Medium -> biasanya 5-7 tahapan
- Complex -> biasanya 7-12 tahapan
- Setiap tahapan harus bisa berdiri sendiri dan deliverable-nya jelas
- Urutkan dari fondasi teknis -> core features -> advanced features -> polish & launch
- Tiap tahapan harus realistis untuk dikerjakan sebagai satu sprint / siklus kerja

Output dalam format JSON berikut (tidak ada teks di luar JSON):
{
  "project_name": "nama project",
  "total_tahapan": 0,
  "tahapan": [
    {
      "nomor": 1,
      "nama_tahapan": "nama singkat",
      "deskripsi": "apa yang dikerjakan di tahapan ini",
      "deliverable": "output konkret yang dihasilkan",
      "dependencies": "tahapan sebelumnya yang harus selesai (tulis 'none' jika tidak ada)",
      "estimasi_durasi": "misal: 1-2 minggu",
      "tech_focus": ["teknologi / area yang jadi fokus"]
    }
  ]
}`;
return [{ json: { prompt } }];

const items = $input.all();
let text = '{}';
try { text = items[0].json.choices[0].message.content; } catch (e) {}
let tahapan_result;
try { tahapan_result = JSON.parse(text); } catch (e) { tahapan_result = { tahapan: [] }; }
if (!Array.isArray(tahapan_result.tahapan)) { tahapan_result.tahapan = []; }
return [{ json: { tahapan_result } }];

const tr = $('Parse Tahapan Result').first().json.tahapan_result;
const list = (tr && Array.isArray(tr.tahapan)) ? tr.tahapan : [];
return list.map(t => ({ json: t }));

const allTahap = $input.all();
const ide = $('Prepare Generate Input').first().json.ide_result;
const allTahapan = $('Parse Tahapan Result').first().json.tahapan_result;
const pref = ($('Prepare Generate Input').first().json.preferensi) ? $('Prepare Generate Input').first().json.preferensi : {};
const designSystem = $('Prepare Generate Input').first().json.design_system || '';
const sertakanStack = (pref.sertakan_tech_stack === undefined) ? true : !!pref.sertakan_tech_stack;
const sertakanKode = (pref.sertakan_kode === undefined) ? true : !!pref.sertakan_kode;
const today = $now.toISODate();
const system = 'Kamu adalah Senior Product Manager yang berpengalaman menulis PRD (Product Requirements Document) yang lengkap, komprehensif, dan langsung bisa dipakai oleh tim engineering dan design. Kamu menulis PRD dalam Bahasa Indonesia yang profesional. Output kamu SELALU dalam format Markdown yang rapi dan SELALU SELESAI sampai akhir bagian (tidak pernah terpotong).';

const konteksProyek = `
## KONTEKS PROJECT:
${JSON.stringify(ide)}

## SEMUA TAHAPAN PROJECT:
${JSON.stringify(allTahapan)}

## TAHAPAN YANG PERLU DIBUATKAN PRD-NYA:
`;

const isiChunk4 = sertakanStack
  ? `## 7. Technical Specifications (arsitektur, tech stack, data model, API endpoints, integrasi)\nCatatan UI: gunakan design system '${designSystem || 'pilihan tim'}' untuk komponen antarmuka.`
  : '## 7. Technical Specifications (arsitektur & desain sistem - TANPA tech stack / teknologi spesifik)';

const aturanKode = sertakanKode
  ? '- Boleh menyertakan snippet kode/konfigurasi singkat bila relevan.'
  : '- JANGAN sertakan kode/coding apa pun (source code, snippet) di dalam PRD. Cukup deskripsi fungsional dan arsitektur dalam bahasa.';

// Pecah PRD menjadi 6 bagian kecil agar setiap panggilan DeepSeek pendek dan PASTI selesai
const chunkDefs = [
  { nomor_chunk: 1, judul_chunk: 'Overview & Objectives', isi: `## 1. Overview Tahapan\n## 2. Objectives & Success Criteria` },
  { nomor_chunk: 2, judul_chunk: 'Scope & User Stories', isi: `## 3. Scope (In Scope / Out of Scope)\n## 4. User Stories & Requirements (minimal 5, beri prioritas P0/P1/P2)` },
  { nomor_chunk: 3, judul_chunk: 'Functional & Non-Functional', isi: `## 5. Functional Requirements (sertakan edge cases dan validasi)\n## 6. Non-Functional Requirements (Performance, Security, Scalability, Accessibility, Compatibility)` },
  { nomor_chunk: 4, judul_chunk: 'Technical Specifications', isi: isiChunk4 },
  { nomor_chunk: 5, judul_chunk: 'UI/UX & Dependencies', isi: `## 8. UI/UX Requirements (halaman, user flow, komponen UI kunci)\n## 9. Dependencies & Risks (minimal 3 risiko + mitigasi)` },
  { nomor_chunk: 6, judul_chunk: 'Timeline, Questions, History & Verifikasi', isi: `## 10. Timeline & Milestones\n## 11. Open Questions\n## 12. Revision History (tabel: Versi | Tanggal | Perubahan | Author). Gunakan tanggal ${today}, author 'PRD Generator'.\n## 13. Verifikasi Penyelesaian Tahapan (Definition of Done)\n\n### 13.1 Daftar Pengujian yang Perlu Dijalankan\nBuat daftar pengujian yang harus dijalankan untuk tahapan ini (minimal 10 butir) dengan format \"- [JENIS] deskripsi skenario uji\" (JENIS: Unit, Integration, E2E, API, Security, Performance, UI/UX, Edge Case, Data/Validasi). Pastikan mencakup user story P0, functional requirement utama, dan skenario validasi.\n\n### 13.2 Kriteria Selesai (Definition of Done)\nTulis checklist verifikasi untuk tahapan ini (setiap butir dengan checkbox). Pastikan mencakup:\n1. Seluruh user story P0 dan P1 terpenuhi.\n2. Setiap functional requirement (FR) utama terpenuhi beserta edge case dan validasinya.\n3. Non-functional requirement (performance, security, scalability, accessibility) terpenuhi.\n4. Deliverable tahapan terkirim dan dapat digunakan.\n5. Dokumentasi lengkap.\n6. Seluruh item Daftar Pengujian (13.1) lolos/pass.` }
];

const hasil = [];
for (const it of allTahap) {
  const tahap = it.json;
  const konteks = konteksProyek + JSON.stringify(tahap) + '\n';
  for (const c of chunkDefs) {
    const bagian = (c.nomor_chunk === 1)
      ? `Tulis PERSIS bagian-bagian berikut (jangan tulis bagian lain):\n# PRD — ${tahap.nama_tahapan}\n\n${c.isi}`
      : `Tulis PERSIS bagian-bagian berikut (jangan tulis bagian lain):\n${c.isi}`;
    hasil.push({
      json: {
        system,
        user: `Kamu sedang menulis PRD untuk sebuah tahapan project. Ini adalah BAGIAN ${c.nomor_chunk} dari ${chunkDefs.length} (bagian: ${c.judul_chunk}).

${konteks}---
${bagian}

---
ATURAN PENTING:
- Tulis HANYA bagian-bagian yang tercantum di atas, dengan heading Markdown yang jelas.
- Detail, komprehensif, dan langsung ke poin.
- JANGAN menulis bagian lain di luar daftar, JANGAN mengulang isi bagian sebelumnya.
- ${aturanKode}
- AKHIRI output kamu dengan baris penanda ini tepat di paling akhir (WAJIB):
<!-- AKHIR BAGIAN ${c.nomor_chunk} -->`,
        nomor: tahap.nomor,
        nama_tahapan: tahap.nama_tahapan,
        estimasi_durasi: tahap.estimasi_durasi,
        tech_focus: tahap.tech_focus,
        deliverable: tahap.deliverable,
        nomor_chunk: c.nomor_chunk,
        total_chunks: chunkDefs.length,
        judul_chunk: c.judul_chunk
      }
    });
  }
}
return hasil;

let content = '';
let finish_reason = '';
try { content = $json.choices[0].message.content || ''; } catch (e) { content = ''; }
try { finish_reason = $json.choices[0].finish_reason || ''; } catch (e) { finish_reason = ''; }
const meta = $('Build PRD Prompt').item.json;
return {
  nomor: meta.nomor,
  nama_tahapan: meta.nama_tahapan,
  estimasi_durasi: meta.estimasi_durasi,
  tech_focus: meta.tech_focus,
  deliverable: meta.deliverable,
  nomor_chunk: meta.nomor_chunk,
  total_chunks: meta.total_chunks,
  judul_chunk: meta.judul_chunk,
  content,
  finish_reason,
  truncated: (finish_reason === 'length'),
};

const chunk = $json;
const system = 'Kamu adalah Senior Product Manager yang berpengalaman menulis PRD (Product Requirements Document) yang lengkap, komprehensif, dan langsung bisa dipakai oleh tim engineering dan design. Kamu menulis PRD dalam Bahasa Indonesia yang profesional. Output kamu SELALU dalam format Markdown yang rapi dan SELALU SELESAI sampai akhir (tidak pernah terpotong).';
const tail = (chunk.content || '').slice(-800);
const user = `Sebelumnya kamu menulis BAGIAN ${chunk.nomor_chunk} dari ${chunk.total_chunks} PRD (bagian: ${chunk.judul_chunk}), tetapi output kamu TERPOTONG sebelum selesai.

Ini AKHIR dari teks yang sudah berhasil kamu tulis:
---
${tail}
---

Tugasmu sekarang:
1. LANJUTKAN penulisan PERSIS dari kalimat/poin terakhir di atas.
2. JANGAN mengulang teks yang sudah ada.
3. Selesaikan SELURUH sisa bagian ${chunk.nomor_chunk} sampai tuntas dan detail, format Markdown rapi.
4. AKHIRI dengan baris penanda ini tepat di paling akhir (WAJIB):
<!-- AKHIR BAGIAN ${chunk.nomor_chunk} -->`;
return { system, user, nomor: chunk.nomor, nama_tahapan: chunk.nama_tahapan, estimasi_durasi: chunk.estimasi_durasi, tech_focus: chunk.tech_focus, deliverable: chunk.deliverable, nomor_chunk: chunk.nomor_chunk, total_chunks: chunk.total_chunks, judul_chunk: chunk.judul_chunk, originalContent: chunk.content };

let cont = '';
let fr = '';
try { cont = $json.choices[0].message.content || ''; } catch (e) { cont = ''; }
try { fr = $json.choices[0].finish_reason || ''; } catch (e) { fr = ''; }
const meta = $('Build Continue Prompt').item.json;
return {
  nomor: meta.nomor,
  nama_tahapan: meta.nama_tahapan,
  estimasi_durasi: meta.estimasi_durasi,
  tech_focus: meta.tech_focus,
  deliverable: meta.deliverable,
  nomor_chunk: meta.nomor_chunk,
  total_chunks: meta.total_chunks,
  judul_chunk: meta.judul_chunk,
  content: (meta.originalContent || '') + String.fromCharCode(10) + String.fromCharCode(10) + cont,
  finish_reason: fr,
  truncated: (fr === 'length'),
};

const allItems = $input.all();
const map = new Map();
for (const item of allItems) {
  const j = item.json || {};
  const key = (j.nomor !== undefined) ? String(j.nomor) : '0';
  if (!map.has(key)) { map.set(key, { meta: j, chunks: [] }); }
  if (j.content) { map.get(key).chunks.push(j); }
}
const hasil = [];
for (const entry of map.values()) {
  const meta = entry.meta;
  const chunks = entry.chunks;
  chunks.sort((a, b) => ((a.nomor_chunk || 0) - (b.nomor_chunk || 0)));
  const safe = String(meta.nama_tahapan || 'tahapan').replace(/ /g, '_').split('/').join('-');
  const missing = [];
  const truncated = [];
  let merged = '';
  for (const c of chunks) {
    const raw = (c.content || '');
    if (!raw.trim()) { missing.push(c.nomor_chunk); }
    else if (c.finish_reason === 'length') { truncated.push(c.nomor_chunk); }
    const cleaned = raw.replace(/<!-- AKHIR BAGIAN \d+ -->/g, '').trim();
    merged += cleaned + String.fromCharCode(10) + String.fromCharCode(10);
  }
  hasil.push({
    json: {
      nomor: meta.nomor,
      nama_tahapan: meta.nama_tahapan,
      estimasi_durasi: meta.estimasi_durasi,
      tech_focus: meta.tech_focus,
      deliverable: meta.deliverable,
      filename: 'PRD_Tahap_' + meta.nomor + '_' + safe + '.md',
      content: merged,
      complete: (missing.length === 0 && truncated.length === 0),
      missing_chunks: missing,
      truncated_chunks: truncated,
    }
  });
}
hasil.sort((a, b) => ((a.json.nomor || 0) - (b.json.nomor || 0)));
return hasil;

const allItems = $input.all();
const ide = $('Prepare Generate Input').first().json.ide_result;
const pref = ($('Prepare Generate Input').first().json.preferensi) ? $('Prepare Generate Input').first().json.preferensi : {};
const designSystem = $('Prepare Generate Input').first().json.design_system || '';
const tahapanMeta = $('Parse Tahapan Result').first().json.tahapan_result;
const prd_files = allItems.map(item => item.json);
const semua_lengkap = prd_files.every(f => f.complete === true);
return [{
  json: {
    success: true,
    data: {
      project_name: ide.project_name,
      platform: ide.platform,
      complexity_level: ide.complexity_level,
      estimasi_skala: ide.estimasi_skala,
      total_tahapan: tahapanMeta.total_tahapan,
      semua_lengkap,
      design_system: designSystem,
      resiko: Array.isArray(ide.resiko) ? ide.resiko : [],
      peluang: Array.isArray(ide.peluang) ? ide.peluang : [],
      analisis_biaya: (ide.analisis_biaya && typeof ide.analisis_biaya === 'object') ? ide.analisis_biaya : null,
      preferensi: pref,
      ide_result: ide,
      tahapan_result: tahapanMeta,
      prd_files,
    },
  },
}];

const body = ($json.body && typeof $json.body === 'object') ? $json.body : {};
const ide_result = (body.analisis && typeof body.analisis === 'object') ? body.analisis : {};
const pref = (body.preferensi && typeof body.preferensi === 'object') ? body.preferensi : {};
const design_system = body.design_system ? String(body.design_system) : '';
return [{ json: { ide_result, preferensi: pref, design_system } }];
